// Parse batch search parameters
const queries = $json.queries || $json.body?.queries || [];
const mode = $json.mode || $json.body?.mode || 'union';
const limit = $json.limit || $json.body?.limit || 5;
const minScore = $json.min_score || $json.body?.min_score || 0.5;

if (!Array.isArray(queries) || queries.length === 0) {
  throw new Error('queries array is required and must not be empty');
}

return {
  json: {
    queries,
    mode,
    limit,
    min_score: minScore
  }
};

// Format batch search results with rich metadata
const response = $json;

if (response.status === 'error') {
  return {
    json: {
      success: false,
      error: response.message || 'Batch search error',
      results: []
    }
  };
}

const results = (response.results || []).map(result => ({
  document_id: result.document_id,
  document_name: result.metadata?.document_name || result.document_name,
  document_type: result.metadata?.document_type || 'unknown',
  department: result.metadata?.department || 'unknown',

  // Content
  content: result.text || result.content,
  content_preview: (result.text || result.content || '').substring(0, 250) + '...',

  // Scores
  relevance_score: result.score || 0,
  quality_score: result.metadata?.quality_score || 0,

  // Batch-specific: which queries matched this result
  matched_queries: result.matched_queries || [],
  match_count: result.matched_queries?.length || 0,

  // Context
  chunk_index: result.chunk_key || result.metadata?.chunk_index,
  document_url: result.metadata?.document_url || null
}));

return {
  json: {
    success: true,
    results,
    metadata: {
      mode: response.metadata?.mode || 'union',
      queries_count: response.metadata?.queries_count || 0,
      total_results: results.length,
      search_type: 'batch',
      min_score_applied: response.metadata?.min_score || 0.7
    }
  }
};
